get.description:
Server-Sent Events stream for a workflow run.

Emits events:
  data: {"event": "step_started", "step_id": "...", "type": "..."}
  data: {"event": "step_completed", "step_id": "...", "output_keys": [...]}
  data: {"event": "step_failed", "step_id": "...", "error": "..."}
  data: {"event": "run_completed", "status": "success", "outputs": {...}}
  data: {"event": "run_failed", "status": "failed", "error": "..."}
  data: [DONE]

schema.example:
data: {"type": "goal_started", "goal": "..."}

data: {"type": "plan_ready", "steps": ["..."]}

data: {"type": "step_started", "step": "..."}

data: {"type": "step_complete", "step": "...", "output": "..."}

data: {"type": "verification_done", "success": true}

data: {"type": "goal_complete"}

post.description:
Run a what-if scenario through the digital twin.

Example scenarios:
  - {"department": "Engineering", "speed_multiplier": 2.0}
  - {"add_agents": 3, "team": "Finance"}

